<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;
use App\Bootstrap\{CanonicalJson,StateStore};use App\Imperium\Runtime\Conscription\{ModelBoundOperationalManifestationAssemblyService,ModelBoundOperationalManifestationSeatBindingService,ModelBoundOperationalProfileQualificationService};use PHPUnit\Framework\TestCase;
final class ModelBoundOperationalQualificationAssemblyBindingTest extends TestCase
{
 public function testQualifiesAssemblesAndBindsExactProfileWhileRemainingInert():void{$root=sys_get_temp_dir().'/imperium-model-bound-operational-'.bin2hex(random_bytes(5));try{$approval=$this->fixtures($root);$state=new StateStore($root);$q=(new ModelBoundOperationalProfileQualificationService($root,$state))->qualify($approval,new \DateTimeImmutable('2026-08-23T20:00:00+00:00'));self::assertSame('PROFILE_OPERATIONALLY_QUALIFIED_PENDING_MANIFESTATION_ASSEMBLY',$q['status']);self::assertTrue($q['profile_installation_scope_consumed']);self::assertTrue($q['profile_installed']);self::assertTrue($q['profile_operationally_qualified']);self::assertSame(['kind'=>'seat','id'=>'foundry.artificer'],$q['intended_seat']);self::assertTrue($q['manifestation_assembly_authority_exercisable']);$a=(new ModelBoundOperationalManifestationAssemblyService($root,$state))->assemble($q['qualification_id']);self::assertSame('OPERATIONAL_MANIFESTATION_ASSEMBLED_PENDING_SEAT_BINDING',$a['status']);self::assertSame($q['source_persona'],$a['manifestation']['persona']);self::assertSame($q['operational_profile'],$a['manifestation']['profile']);self::assertSame($q['substrate_contract'],$a['manifestation']['substrate']);self::assertFalse($a['seat_bound']);self::assertTrue($a['seat_binding_authority_exercisable']);$b=(new ModelBoundOperationalManifestationSeatBindingService($root,$state))->bind($a['assembly_id']);self::assertSame('OPERATIONAL_MANIFESTATION_BOUND_PENDING_DEPLOYMENT_AUTHORIZATION',$b['status']);self::assertSame('foundry.artificer',$b['seat']);self::assertSame(1,$b['occupancy_generation']);self::assertTrue($b['binding_atomic']);self::assertTrue($b['seat_bound']);self::assertTrue($b['deployment_authorization_pending']);foreach(['operational_use_permitted','deployment_authority','custody_transfer_authority','tool_use_authority','credential_use_authority','external_action_authority','execution_authority']as$f)self::assertFalse($b[$f]);self::assertSame($q,(new ModelBoundOperationalProfileQualificationService($root,$state))->qualify($approval,new \DateTimeImmutable('2026-08-23T20:00:00+00:00')));self::assertSame($a,(new ModelBoundOperationalManifestationAssemblyService($root,$state))->assemble($q['qualification_id']));self::assertSame($b,(new ModelBoundOperationalManifestationSeatBindingService($root,$state))->bind($a['assembly_id']));}finally{$this->remove($root);}}
 public function testQualificationRejectsChangedApprovalAuthority():void{$root=sys_get_temp_dir().'/imperium-model-bound-operational-invalid-'.bin2hex(random_bytes(5));try{$approval=$this->fixtures($root);$path=$root.'/var/imperium/imperator/model-bound-profile-approval-decisions/'.$approval.'.json';$a=json_decode((string)file_get_contents($path),true);$a['operational_qualification_request']['consumed']=true;$a=$this->record($a);$this->write($path,$a);$this->expectExceptionMessage('R204_MODEL_BOUND_QUALIFICATION_CHAIN_INVALID');(new ModelBoundOperationalProfileQualificationService($root,new StateStore($root)))->qualify($approval,new \DateTimeImmutable('2026-08-23T20:00:00+00:00'));}finally{$this->remove($root);}}
 private function fixtures(string$root):string{$instance='imperium-test';$profile=['contract_version'=>'1.0.0','profile_id'=>'profile-foundry-artificer','profile_version'=>'1.1.0','artifact_class'=>'officer','source_persona'=>['persona_id'=>'persona-artificer','persona_version'=>'1.0.0','persona_digest'=>'sha256:'.str_repeat('a',64),'admission_state'=>'admitted','evidence_record'=>'evidence-artificer'],'steward'=>['kind'=>'office','id'=>'foundry'],'target'=>['kind'=>'seat','id'=>'foundry.artificer'],'transformation'=>['case_id'=>'case','specification_version'=>'1.0.0','alchemist_disposition_id'=>'disposition'],'cognitive_payload'=>['role'=>'Artificer'],'model_binding'=>['provider_model_version'=>'openai/gpt-test@2026-08-01','configuration'=>['temperature'=>0.2]],'qualification_contract'=>['contract_id'=>'qualification','criteria'=>['Preserve provenance.']],'limitations'=>['No execution authority.'],'lineage'=>['derived_from'=>'persona-artificer@1.0.0'],'digest_spec'=>['algorithm'=>'sha256']];$profile['content_digest']='sha256:'.hash('sha256',CanonicalJson::encode($profile));$authId='mission-authorization-'.str_repeat('b',20);$auth=$this->record(['schema'=>'imperium.mission-authorization/v1','authorization_id'=>$authId,'instance_id'=>$instance,'status'=>'MISSION_AUTHORIZATION_SEALED_PENDING_AUTHORIZED_PREPARATION','sealed'=>true]);$bindId='profile-model-binding-'.str_repeat('c',20);$binding=$this->record(['schema'=>'imperium.conscription-profile-model-binding/v1','binding_id'=>$bindId,'instance_id'=>$instance,'mission_authorization'=>['id'=>$authId,'digest'=>$auth['record_digest']],'sealed_profile'=>$profile,'sealed'=>true]);$attId='profile-model-access-attestation-'.str_repeat('d',20);$att=$this->record(['schema'=>'imperium.clavium-profile-model-access-attestation/v1','attestation_id'=>$attId,'instance_id'=>$instance,'model_binding'=>['binding_id'=>$bindId,'binding_digest'=>$binding['record_digest']],'provider_access_evidence'=>['expires_at'=>'2026-08-24T20:00:00+00:00'],'status'=>'ACCESS_AVAILABLE','sealed'=>true]);$subject=['profile_id'=>$profile['profile_id'],'profile_version'=>$profile['profile_version'],'content_digest'=>$profile['content_digest'],'target'=>$profile['target']];$dispId='model-bound-profile-disposition-'.str_repeat('e',20);$disp=$this->record(['schema'=>'imperium.senate-model-bound-profile-disposition/v1','disposition_id'=>$dispId,'subject_profile'=>$subject,'decision'=>['disposition'=>'APPROVED'],'mandatory_security_blocking_condition'=>false,'sealed'=>true]);$approvalId='model-bound-profile-approval-decision-'.str_repeat('f',20);$approval=$this->record(['schema'=>'imperium.imperator-model-bound-profile-approval-decision/v1','decision_id'=>$approvalId,'instance_id'=>$instance,'case_id'=>'case','case_digest'=>str_repeat('1',64),'source_senate_disposition'=>['id'=>$dispId,'digest'=>$disp['record_digest'],'decision'=>$disp['decision']],'subject_profile'=>$subject,'disposition'=>'APPROVED','status'=>'IMPERATOR_PROFILE_APPROVED_PENDING_CONSCRIPTION_OPERATIONAL_QUALIFICATION','profile_approved'=>true,'operational_qualification_request_authority'=>true,'operational_qualification_request'=>['authority_id'=>'operational-qualification-request-authority-'.str_repeat('2',20),'authority_single_use'=>true,'destination'=>'conscription.recruiter','purpose'=>'REQUEST_ONE_EXACT_OPERATIONAL_PROFILE_QUALIFICATION','consumed'=>false],'operational_qualification_authority'=>false,'profile_installation_authority'=>false,'profile_activation_authority'=>false,'manifestation_assembly_authority'=>false,'seat_binding_authority'=>false,'deployment_authority'=>false,'custody_transfer_authority'=>false,'tool_use_authority'=>false,'credential_use_authority'=>false,'external_action_authority'=>false,'execution_authority'=>false,'sealed'=>true]);$this->write($root.'/var/imperium/authorizations/missions/'.$authId.'.json',$auth);$this->write($root.'/var/imperium/offices/conscription/profile-model-bindings/'.$bindId.'.json',$binding);$this->write($root.'/var/imperium/offices/clavium/profile-model-access-attestations/'.$attId.'.json',$att);$this->write($root.'/var/imperium/offices/senate/model-bound-profile-dispositions/'.$dispId.'.json',$disp);$this->write($root.'/var/imperium/imperator/model-bound-profile-approval-decisions/'.$approvalId.'.json',$approval);$state=new StateStore($root);if(!is_dir($root.'/var/imperium'))mkdir($root.'/var/imperium',0770,true);$state->write(['state'=>'CURIA_READY','binding'=>['instance_id'=>$instance],'events'=>[['transition'=>'T04','result'=>'SUCCESS','output'=>['successor'=>['manifestation_id'=>'recruiter-1','seat'=>'conscription.recruiter','occupancy_generation'=>2,'authority'=>'ordinary-recruiter']]]]]);return$approvalId;}
 private function record(array$r):array{unset($r['record_digest']);$r['record_digest']=hash('sha256',CanonicalJson::encode($r));return$r;}private function write($p,$r):void{if(!is_dir(dirname($p)))mkdir(dirname($p),0770,true);file_put_contents($p,json_encode($r));}private function remove($p):void{if(!is_dir($p))return;foreach(array_diff(scandir($p),['.','..'])as$e){$c=$p.'/'.$e;is_dir($c)?$this->remove($c):unlink($c);}rmdir($p);}
}
